return $input.all().map((item, index) => {
  const customer = item.json;

  const fullName = String(
    customer.full_name ?? ""
  ).trim();

  const nameParts = fullName.split(/\s+/);

  const firstName = nameParts[0] ?? "";
  const lastName = nameParts.slice(1).join(" ");

  const email = String(
    customer.primary_email ?? ""
  ).trim().toLowerCase();

  const properties = {
    email
  };

  if (firstName) {
    properties.firstname = firstName;
  }

  if (lastName) {
    properties.lastname = lastName;
  }

  if (customer.phone) {
    properties.phone = customer.phone;
  }

  if (customer.company) {
    properties.company = customer.company;
  }

  return {
    json: {
      job_id: customer.job_id,
      customer_id: customer.customer_id,
      claim_token: customer.claim_token,
      attempt_count: customer.attempt_count,
      email,
      properties,
      existing_hubspot_id:
        customer.hubspot_contact_id ?? null
    },
    pairedItem: { item: index }
  };
});

