const search = $input.first().json;

const original = $("PrepareHubSpotContact")
  .first().json;

const results = search.results;

if (!Array.isArray(results)) {
  throw new Error("Invalid HubSpot search response");
}

if (results.length > 1 || Number(search.total) > 1) {
  throw new Error(
    "Ambiguous HubSpot match: multiple contacts found"
  );
}

if (results.length === 1) {
  const hubspotEmail = String(
    results[0].properties?.email ?? ""
  ).trim().toLowerCase();

  if (hubspotEmail !== original.email) {
    throw new Error("HubSpot email mismatch");
  }
}

return [{
  json: {
    ...original,
    found_existing: results.length === 1,
    hubspot_id: results[0]?.id ?? null
  }
}];

return $input.all().map(item => ({
  json: {
    job_id: item.json.job_id,
    customer_id: item.json.customer_id,
    claim_token: item.json.claim_token,
    hubspot_id: item.json.hubspot_id,
    sync_action: "matched_existing"
  }
}));

const response = $input.first().json;

const original = $("CheckHubspotMatch")
  .first().json;

if (!response.id) {
  throw new Error("HubSpot did not return a contact ID");
}

if (
  String(response.properties?.email ?? "")
    .trim().toLowerCase() !== original.email
) {
  throw new Error("Created contact email mismatch");
}

return [{
  json: {
    job_id: original.job_id,
    customer_id: original.customer_id,
    claim_token: original.claim_token,
    hubspot_id: String(response.id),
    sync_action: "created"
  }
}];
